-- =====================================================================
-- dim_customer: SCD TYPE 2. GRAIN: one row = one address VERSION of one person.
--
-- Unlike phase 2 (SCD1, one person = one row, overwritten):
--   customer moves SP -> RJ  =>  2 rows:  [SP, valid 1900..move date]  [RJ, valid move date..9999]
--   Orders placed BEFORE the move link to the SP version, orders AFTER link to RJ. History is not rewritten.
--
-- customer_key = dbt_scd_id: a hash generated by dbt (unique_key + timestamp). Stable across runs,
-- unlike ROW_NUMBER() in phase 2 (renumbered on every rebuild -> unusable with incremental facts).
-- =====================================================================
with snap as (
    select * from {{ ref('snap_customer_address') }}
),

order_stats as (
    select
        c.customer_unique_id,
        min(o.order_purchase_timestamp) as first_order_at,
        max(o.order_purchase_timestamp) as last_order_at,
        count(*)                        as order_count
    from {{ ref('stg_orders') }} o
    join {{ ref('stg_customers') }} c using (customer_id)
    group by 1
)

select
    s.dbt_scd_id                                    as customer_key,
    s.customer_unique_id,
    s.city,
    s.state,
    s.zip_code_prefix,
    -- The first version is treated as valid "since forever": historical data loaded on the first run
    -- must still attach to it (the snapshot only starts capturing from today).
    case when row_number() over (partition by s.customer_unique_id order by s.dbt_valid_from) = 1
         then timestamp '1900-01-01' else s.dbt_valid_from end as valid_from,
    coalesce(s.dbt_valid_to, timestamp '9999-12-31') as valid_to,
    s.dbt_valid_to is null                           as is_current,
    st.first_order_at,
    st.last_order_at,
    coalesce(st.order_count, 0)                      as order_count,
    coalesce(st.order_count, 0) > 1                  as is_repeat_customer
from snap s
left join order_stats st using (customer_unique_id)

union all

select '-1', 'unknown', 'unknown', 'unknown', '00000',
       timestamp '1900-01-01', timestamp '9999-12-31', true, null, null, 0, false
